## 4. Teste de regressão executável

Prova que, após ~5s, o `signal` é abortado e o `fetch` encerra (não fica “órfão”).

```typescript
// processJob.abort.test.ts
// Executar: npx tsx processJob.abort.test.ts
// (runner: não informado no pacote; script auto-contido)

import assert from 'node:assert/strict';

// --- stubs do contrato do pacote ---
function timeout(ms: number) {
  return new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms));
}

// Implementação sob teste (espelha o patch com abort ON)
async function processJob(id: string, deps: any) {
  const useAbort =
    deps.config?.useFetchAbort !== false && process.env.USE_FETCH_ABORT !== 'false';

  if (!useAbort) {
    const result = await Promise.race([deps.client.fetch(id), timeout(5000)]);
    await deps.queue.ack(id);
    return result;
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5000);
  const started = Date.now();
  try {
    const result = await deps.client.fetch(id, { signal: controller.signal });
    await deps.queue.ack(id);
    deps.metrics?.inc?.('job_process_ok', { id });
    return result;
  } catch (err: any) {
    const aborted =
      controller.signal.aborted ||
      err?.name === 'AbortError' ||
      err?.code === 'ABORT_ERR';
    if (aborted) {
      deps.metrics?.inc?.('job_fetch_aborted', { id, ms: Date.now() - started });
      deps.logger?.warn?.({ id, event: 'fetch_aborted', ms: Date.now() - started });
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

async function main() {
  let sawAbort = false;
  let fetchStillRunningAfterRace = false;
  let acked = false;
  const metrics: string[] = [];

  const deps = {
    config: { useFetchAbort: true },
    metrics: { inc: (n: string) => metrics.push(n) },
    logger: { warn: () => {}, error: () => {} },
    queue: {
      ack: async () => {
        acked = true;
      },
    },
    client: {
      fetch: (id: string, opts?: { signal?: AbortSignal }) =>
        new Promise((resolve, reject) => {
          const t = setTimeout(() => {
            fetchStillRunningAfterRace = true;
            resolve({ id, slow: true });
          }, 30_000); // “HTTP lento” — não deve completar se abort funcionar

          opts?.signal?.addEventListener('abort', () => {
            clearTimeout(t);
            sawAbort = true;
            const e = new Error('aborted');
            (e as any).name = 'AbortError';
            reject(e);
          });
        }),
    },
  };

  const t0 = Date.now();
  let threw = false;
  try {
    await processJob('job-1', deps);
  } catch {
    threw = true;
  }
  const elapsed = Date.now() - t0;

  assert.equal(threw, true, 'deve falhar no timeout/abort');
  assert.equal(acked, false, 'não deve ack após abort');
  assert.equal(sawAbort, true, 'AbortSignal deve disparar no fetch');
  assert.equal(fetchStillRunningAfterRace, false, 'fetch não pode completar após abort');
  assert.ok(elapsed >= 4900 && elapsed < 8000, `abort ~5s, got ${elapsed}ms`);
  assert.ok(metrics.includes('job_fetch_aborted'), 'métrica de abort');

  console.log('PASS: abort após ~5s, sem ack, fetch cancelado, métrica emitida');
}

main().catch((e) => {
  console.error('FAIL', e);
  process.exit(1);
});
```

**O que o teste prova (fato do desenho do teste):** abort do signal ~5s, sem `ack`, Promise do fetch não resolve depois, contador `job_fetch_aborted`.  
**Não prova em produção:** requeue real, cancelamento de socket real, multi-instância — **não informado / ABSTENÇÃO** até validação no ambiente real.

